const source = "// vgsl-module: F:\\avishkarai2\\components\\hero\\triangle-led-front\\shaders\\led-emitters.wgsl\nstruct _vgsl_82ed982f__Config {\n  resolution: vec2f,\n  tunables: vec4f,\n  triangle: vec4f,\n  led_clip: vec4f,\n};\nstruct _vgsl_82ed982f__Led {\n  pos_brightness: vec4f,\n  color: vec4f,\n};\n@group(0) @binding(0) var<uniform> cfg: _vgsl_82ed982f__Config;\n@group(0) @binding(1) var<storage, read> leds: array<_vgsl_82ed982f__Led>;\n\nstruct _vgsl_82ed982f__VSIn {\n  @location(0) position: vec2f,\n  @location(1) led_index: f32,\n};\nstruct _vgsl_82ed982f__VSOut {\n  @builtin(position) pos: vec4f,\n  @location(0) led_index: f32,\n};\n\n@vertex fn vs_main(in: _vgsl_82ed982f__VSIn) -> _vgsl_82ed982f__VSOut {\n  var out: _vgsl_82ed982f__VSOut;\n  let clip = (in.position / cfg.resolution) * vec2f(2.0, -2.0) + vec2f(-1.0, 1.0);\n  out.pos = vec4f(clip, 0.0, 1.0);\n  out.led_index = in.led_index;\n  return out;\n}\n\nfn _vgsl_82ed982f__signed_triangle_area(a: vec2f, b: vec2f, p: vec2f) -> f32 {\n  let edge = b - a;\n  return edge.x * (p.y - a.y) - edge.y * (p.x - a.x);\n}\nfn _vgsl_82ed982f__inside_triangle(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> bool {\n  let side0 = _vgsl_82ed982f__signed_triangle_area(a, b, p);\n  let side1 = _vgsl_82ed982f__signed_triangle_area(b, c, p);\n  let side2 = _vgsl_82ed982f__signed_triangle_area(c, a, p);\n  return (side0 <= 0.0 && side1 <= 0.0 && side2 <= 0.0) || (side0 >= 0.0 && side1 >= 0.0 && side2 >= 0.0);\n}\nfn _vgsl_82ed982f__segment_distance(p: vec2f, a: vec2f, b: vec2f) -> f32 {\n  let pa = p - a;\n  let ba = b - a;\n  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  return length(pa - ba * h);\n}\nfn _vgsl_82ed982f__triangle_sdf(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> f32 {\n  let edge_dist = min(_vgsl_82ed982f__segment_distance(p, a, b), min(_vgsl_82ed982f__segment_distance(p, b, c), _vgsl_82ed982f__segment_distance(p, c, a)));\n  return select(edge_dist, -edge_dist, _vgsl_82ed982f__inside_triangle(p, a, b, c));\n}\n\n@fragment fn fs_main(in: _vgsl_82ed982f__VSOut) -> @location(0) vec4f {\n  let pixel = in.pos.xy;\n  let top = vec2f(cfg.triangle.x, cfg.triangle.y - cfg.triangle.z);\n  let left = vec2f(cfg.triangle.x - cfg.triangle.w, cfg.triangle.y + cfg.triangle.z * 0.5);\n  let right = vec2f(cfg.triangle.x + cfg.triangle.w, cfg.triangle.y + cfg.triangle.z * 0.5);\n  let tri_dist = _vgsl_82ed982f__triangle_sdf(pixel, top, left, right);\n  // Positive expansion reveals emitter pixels outside the canonical triangle.\n  if (tri_dist - cfg.led_clip.x > 0.0) {\n    discard;\n  }\n\n  let raw_index = u32(max(round(in.led_index), 0.0));\n  let i = min(raw_index, arrayLength(&leds) - 1u);\n  let n01 = clamp(leds[i].pos_brightness.z, 0.0, 1.0);\n  let intensity = mix(cfg.tunables.y, cfg.tunables.z, n01);\n  let emit = leds[i].color.rgb * cfg.tunables.x * intensity;\n  // Alpha (the LED SDF) is masked off by the pipeline writeMask (0x7 = RGB only) — the fullscreen\n  // prepass owns the SDF — so the led_dist that used to go here is never written. Skip computing it.\n  return vec4f(emit, 0.0);\n}\n";
